+  if (!op.pattern) return blocks;
+  let regex: RegExp;
+  try {
+    regex = new RegExp(op.pattern, op.flags ?? "u");
+  } catch {
+    return blocks;
+  }
+  return blocks.map((block) => {
+    if (!isTextBlock(block)) return block;
+    return { ...block, text: block.text.replace(regex, op.replacement) };
+  });
